  /// A KaamNishaan company whose owner has this email, if any
  final String? companyId;
  final String? companyName;
  final DateTime createdAt;
  final String email;
  final DateTime? handledAt;
  /// Staff name
  final String? handledBy;
  final String id;
  /// One of: demo, contact, newsletter
  final String kind;
  final String lang;
  final String? message;
  final String name;
  final String? note;
  /// Shown as KN-20001
  final int number;
  final String? phone;
  /// Start of the message
  final String? preview;
  /// Demo time
  final DateTime? startsAt;
  /// One of: new, contacted, done, spam
  final String status;
  final String? teamSize;
  final String? topic;
  /// Industry name in the asked language
  final String? trade;

  const AdminLeadDetailModel({
    this.company,
    this.companyId,
    this.companyName,
    required this.createdAt,
    required this.email,
    this.handledAt,
    this.handledBy,
    required this.id,
    required this.kind,
    required this.lang,
    this.message,
    required this.name,
    this.note,
    required this.number,
    this.phone,
    this.preview,
    this.startsAt,
    required this.status,
    this.teamSize,
    this.topic,
    this.trade,
  });

  factory AdminLeadDetailModel.fromJson(Map<String, dynamic> json) => AdminLeadDetailModel(
        company: json['company'] as String?,
        companyId: json['company_id'] as String?,
        companyName: json['company_name'] as String?,
        createdAt: DateTime.parse(json['created_at'] as String),
        email: json['email'] as String,
        handledAt: json['handled_at'] == null ? null : DateTime.parse(json['handled_at'] as String),
        handledBy: json['handled_by'] as String?,
        id: json['id'] as String,
        kind: json['kind'] as String,
        lang: json['lang'] as String,
        message: json['message'] as String?,
        name: json['name'] as String,
        note: json['note'] as String?,
        number: (json['number'] as num).toInt(),
        phone: json['phone'] as String?,
        preview: json['preview'] as String?,
        startsAt: json['starts_at'] == null ? null : DateTime.parse(json['starts_at'] as String),
        status: json['status'] as String,
        teamSize: json['team_size'] as String?,
        topic: json['topic'] as String?,
        trade: json['trade'] as String?,
      );

  Map<String, dynamic> toJson() => {
        'company': company,
        'company_id': companyId,
        'company_name': companyName,
        'created_at': createdAt.toIso8601String(),
        'email': email,
        'handled_at': handledAt?.toIso8601String(),
        'handled_by': handledBy,
        'id': id,
        'kind': kind,
        'lang': lang,
        'message': message,
        'name': name,
        'note': note,
        'number': number,
        'phone': phone,
        'preview': preview,
        'starts_at': startsAt?.toIso8601String(),
        'status': status,
        'team_size': teamSize,
        'topic': topic,
        'trade': trade,
      };
}

